 * 장치트리의인터럽트specifier를parent/map/mask로번역해LinuxIRQdomain/번호/resource에연결하고controller의존초기화와MSI관계를준비하는원리를읽습니다.
 * map처리단계에서addrsize>0인데addr가NULL이면실패합니다. map이없으면of_irq_find_parent로새parent를얻어다음수준을처리합니다. 주소계층상승과IRQ관계상승이같은callback이라고판정하지않습니다.
 * 주소필요/NULL의분기와nomap→newparent경로를그립니다. 최종controller조기종료가이검사보다앞이라는순서도원문에서표시합니다.
 */
int of_irq_parse_raw(const __be32 *addr, struct of_phandle_args *out_irq)
{
	struct device_node *ipar, *tnode, *old = NULL;
	__be32 initial_match_array[MAX_PHANDLE_ARGS];
	const __be32 *match_array = initial_match_array;
	const __be32 *tmp, dummy_imask[] = { [0 ... MAX_PHANDLE_ARGS] = cpu_to_be32(~0) };
	u32 intsize = 1, addrsize;
	int i, rc = -EINVAL;

#ifdef DEBUG
	of_print_phandle_args("of_irq_parse_raw: ", out_irq);
#endif

	ipar = of_node_get(out_irq->np);

	/* First get the #interrupt-cells property of the current cursor
	 * that tells us how to interpret the passed-in intspec. If there
	 * is none, we are nice and just walk up the tree
