/* 학습 해설
 * OF IRQ parseone·OldWorld와3cell주소buffer
 * 장치트리의인터럽트specifier를parent/map/mask로번역해LinuxIRQdomain/번호/resource에연결하고controller의존초기화와MSI관계를준비하는원리를읽습니다.
 * OldWorldworkaround면별도parser에위임합니다. 일반은reg를주소buffer3cell에최대sizeof만복사하고나머지는초기0입니다. 이주소buffer와raw가읽는addrsize의정상caller조건을같이확인해야하며복사상한만으로모든임의주소폭이안전하다고판정하지않습니다.
 * reg길이4/12/16의실제복사량4/12/12를계산합니다. raw주소요구폭과주어진buffer길이,OldWorld구현은이파일밖이라는범위를표시합니다.
 */
int of_irq_parse_one(struct device_node *device, int index, struct of_phandle_args *out_irq)
{
	struct device_node *p;
	const __be32 *addr;
	u32 intsize;
	int i, res, addr_len;
	__be32 addr_buf[3] = { 0 };

	pr_debug("of_irq_parse_one: dev=%pOF, index=%d\n", device, index);

	/* OldWorld mac stuff is "special", handle out of line */
	if (of_irq_workarounds & OF_IMAP_OLDWORLD_MAC)
		return of_irq_parse_oldworld(device, index, out_irq);

	/* Get the reg property (if any) */
	addr = of_get_property(device, "reg", &addr_len);

	/* Prevent out-of-bounds read in case of longer interrupt parent address size */
	if (addr_len > sizeof(addr_buf))
		addr_len = sizeof(addr_buf);
