/* 학습 해설
 * OF IRQ resource·virq0와선택output
 * 장치트리의인터럽트specifier를parent/map/mask로번역해LinuxIRQdomain/번호/resource에연결하고controller의존초기화와MSI관계를준비하는원리를읽습니다.
 * get의음수오류는반환합니다. r과irq둘다유효nonzero일때만resource를0으로초기화하고interrupt-names또는nodefullname을이름으로쓰며IRQtriggerflags를OR합니다. irq0은resource를작성하지않고0으로반환합니다.
 * providerfixture의음수/0/55와rNULL,선택이름/fallback을읽습니다. resource중립화시점과mapping실패0에서기존sentinel유지를주석달아봅니다.
 */
int of_irq_to_resource(struct device_node *dev, int index, struct resource *r)
{
	int irq = of_irq_get(dev, index);

	if (irq < 0)
		return irq;

	/* Only dereference the resource if both the
	 * resource and the irq are valid. */
	if (r && irq) {
		const char *name = NULL;

		memset(r, 0, sizeof(*r));
		/*
		 * Get optional "interrupt-names" property to add a name
		 * to the resource.
		 */
		of_property_read_string_index(dev, "interrupt-names", index,
					      &name);

		*r = DEFINE_RES_IRQ_NAMED(irq, name ?: of_node_full_name(dev));
		r->flags |= irq_get_trigger_type(irq);
	}

	return irq;
}

