/* 학습 해설
 * OF IRQ get·domain부재의probe defer
 * 장치트리의인터럽트specifier를parent/map/mask로번역해LinuxIRQdomain/번호/resource에연결하고controller의존초기화와MSI관계를준비하는원리를읽습니다.
 * parse실패는그status입니다. 정상specifier의irqdomain을찾아없으면EPROBE_DEFER,있으면mapping결과를받고out에서np를put합니다. mapping0은음수defer와다른실패표현입니다. controllerdriver준비시점과의존성을다루는deferredprobe기술입니다.
 * fixture의parseEINVAL/domain없음-517/mapping0/mapping55와put계산을표로적습니다. provider가domainlookup/mapping을대체하며실제IRQ할당/발생은검증하지않았음을표시합니다.
 */
int of_irq_get(struct device_node *dev, int index)
{
	int rc;
	struct of_phandle_args oirq;
	struct irq_domain *domain;

	rc = of_irq_parse_one(dev, index, &oirq);
	if (rc)
		return rc;

	domain = irq_find_host(oirq.np);
	if (!domain) {
		rc = -EPROBE_DEFER;
		goto out;
	}

	rc = irq_create_of_mapping(&oirq);
out:
	of_node_put(oirq.np);

	return rc;
}
EXPORT_SYMBOL_GPL(of_irq_get);

